) TEMP ) de ) AS B set A.PROD_ID = B.PROD_ID, A.FPROD_ID = B.FPROD_ID, A.TRADE_TYPE = B.TRADE_TYPE, A.SETTDATE_DATE = B.SETTDATE_DATE, A.REG_DATE = B.REG_DATE, A.PAY_DATE = B.PAY_DATE, A.REG_TRADE_QTY = B.REG_TRADE_QTY, A.TRADE_QTY = B.TRADE_QTY, A.TRADE_AMT = B.TRADE_AMT, A.INT_AMT = B.INT_AMT, A.STATUS = B.STATUS, A.REV_DATE = B.REV_DATE, A.REMARK = B.REMARK, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.CREATE_USER = B.CREATE_USER, A.CREATE_TIME = B.CREATE_TIME, A.ORG_CODE = B.ORG_CODE, A.CREATE_DEPT = B.CREATE_DEPT where A.TRADE_ID = B.TRADE_ID ;
